<?php
namespace Tests\Feature;use App\Models\{Room,RoomMember,User};use Illuminate\Foundation\Testing\RefreshDatabase;use Tests\TestCase;
class SearchTest extends TestCase{use RefreshDatabase;public function test_search_finds_people_and_rooms_but_hides_blocked_users():void{$me=User::factory()->create();$visible=User::factory()->create(['name'=>'Nour Star']);$blocked=User::factory()->create(['name'=>'Nour Hidden']);$blocked->blockedUsers()->attach($me);$room=Room::create(['name'=>'Nour Lounge','host_user_id'=>$visible->id]);RoomMember::create(['room_id'=>$room->id,'user_id'=>$visible->id]);$this->actingAs($me)->getJson('/api/search?q=Nour')->assertOk()->assertJsonCount(1,'users')->assertJsonPath('users.0.name','Nour Star')->assertJsonPath('rooms.0.name','Nour Lounge');}public function test_search_requires_two_characters():void{$this->actingAs(User::factory()->create())->getJson('/api/search?q=a')->assertUnprocessable();}}
